import 'dart:math' as math;
import 'package:geolocator/geolocator.dart';
class LocationService{static Future<Position> current()async{if(!await Geolocator.isLocationServiceEnabled())throw Exception('Location services are disabled.');var p=await Geolocator.checkPermission();if(p==LocationPermission.denied)p=await Geolocator.requestPermission();if(p==LocationPermission.denied||p==LocationPermission.deniedForever)throw Exception('Location permission is required.');return Geolocator.getCurrentPosition(locationSettings:const LocationSettings(accuracy:LocationAccuracy.high));}static Stream<Position> stream()=>Geolocator.getPositionStream(locationSettings:const LocationSettings(accuracy:LocationAccuracy.high,distanceFilter:10));static double distanceKm(double a,double b,double c,double d){const r=6371.0;final x=(c-a)*math.pi/180,y=(d-b)*math.pi/180;final q=math.sin(x/2)*math.sin(x/2)+math.cos(a*math.pi/180)*math.cos(c*math.pi/180)*math.sin(y/2)*math.sin(y/2);return r*2*math.atan2(math.sqrt(q),math.sqrt(1-q));}}
